    if(engine.seen[engine.key(engine.stairs.x,engine.stairs.y)]){const sx=engine.stairs.x*tile+offsetX,sy=engine.stairs.y*tile+offsetY;if(engine.floor===10&&engine.visible[engine.key(engine.stairs.x,engine.stairs.y)])drawLantern(sx,sy);else drawStairs(sx,sy);if(!engine.visible[engine.key(engine.stairs.x,engine.stairs.y)]){ctx.fillStyle='#0b111a99';ctx.fillRect(sx,sy,tile,tile);}}
